$output = "scan_krs_summary.txt"; "=== RINGKASAN STRUKTUR & KODE KRS PROYEK SIAKAD ===" | Out-File -FilePath $output -Encoding utf8; Add-Content -Path $output -Value "`n1. RUTING KRS DI routes/web.php:"; if (Test-Path "routes/web.php") { Select-String -Path "routes/web.php" -Pattern "krs", "PortalKrs", "KrsController" | ForEach-Object { $_.Line } | Out-File -FilePath $output -Append -Encoding utf8 }; Add-Content -Path$output -Value "`n2. CONTROLLER & MODEL KRS:"; Get-ChildItem -Path "app/Http/Controllers", "app/Models" -Recurse -Filter "*Krs*.php" -ErrorAction SilentlyContinue | ForEach-Object { Add-Content -Path $output -Value "`n=== FILE: $($_.FullName) ==="; Get-Content -Path $_.FullName | Out-File -FilePath $output -Append -Encoding utf8 }; Add-Content -Path$output -Value "`n3. VIEW BLADE KRS:"; Get-ChildItem -Path "resources/views" -Recurse -Filter "*.blade.php" -ErrorAction SilentlyContinue | Where-Object { $_.FullName -like "*krs*" } | ForEach-Object { Add-Content -Path $output -Value "`n=== FILE: $($_.FullName) ==="; Get-Content -Path $_.FullName \vert{} Out-File -FilePath$output -Append -Encoding utf8 }; Write-Host "Pindaian selesai! Hasil disimpan di: scan_krs_summary.txt" -ForegroundColor Green
